priceLine(line, tiers, options) {
    let unit = line.unitPrice;

    for (let i = 0; i < tiers.length; i++) {
        const tier = tiers[i];
        const next = tiers[i + 1];

        if (line.quantity >= tier.minQuantity && line.quantity < next.minQuantity) {
            unit = tier.unitPrice;
            break;
        }
    }

